double now_ms() {
    using namespace std::chrono;
    return duration<double, std::milli>(steady_clock::now().time_since_epoch()).count();
}

transcribe_backend_request parse_backend(const char * s) {
    if (!std::strcmp(s, "cpu")) {
        return TRANSCRIBE_BACKEND_CPU;
    }
    if (!std::strcmp(s, "cpu_accel")) {
        return TRANSCRIBE_BACKEND_CPU_ACCEL;
    }
    if (!std::strcmp(s, "metal")) {
        return TRANSCRIBE_BACKEND_METAL;
    }
    if (!std::strcmp(s, "vulkan")) {
        return TRANSCRIBE_BACKEND_VULKAN;
    }
    if (!std::strcmp(s, "cuda")) {
        return TRANSCRIBE_BACKEND_CUDA;
    }
    if (!std::strcmp(s, "rocm")) {
        return TRANSCRIBE_BACKEND_ROCM;
    }
    return TRANSCRIBE_BACKEND_AUTO;
}

std::vector<int> parse_sizes(const std::string & csv) {
    std::vector<int> out;
    size_t           i = 0;
    while (i < csv.size()) {
        size_t j = csv.find(',', i);
        if (j == std::string::npos) {
            j = csv.size();
        }
        const std::string tok = csv.substr(i, j - i);
        if (!tok.empty()) {
            const int n = std::atoi(tok.c_str());
            if (n > 0) {
                out.push_back(n);
            }
        }
        i = j + 1;
    }
    return out;
}

std::string json_escape(const std::string & s) {
    std::string o;
    for (char c : s) {
        if (c == '"' || c == '\\') {
            o += '\\';
            o += c;
        } else if (c == '\n') {
            o += "\\n";
        } else {
            o += c;
        }
    }
    return o;
}

int main(int argc, char ** argv) {
    std::string                model_path;
    std::string                wav_path;
    std::string                out_path;
    std::string                sizes_csv = "1,2,4,8,16,32";
    transcribe_backend_request backend   = TRANSCRIBE_BACKEND_AUTO;
    int                        iters     = 3;
    int                        n_threads = 0;

    for (int i = 1; i < argc; ++i) {
        const std::string a    = argv[i];
        auto              next = [&](const char * flag) -> const char * {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "error: %s needs a value\n", flag);
                std::exit(2);
            }
            return argv[++i];
        };
        if (a == "-m" || a == "--model") {
            model_path = next(a.c_str());
        } else if (a == "--backend") {
            backend = parse_backend(next(a.c_str()));
        } else if (a == "--batch-sizes") {
            sizes_csv = next(a.c_str());
        } else if (a == "--iters") {
            iters = std::atoi(next(a.c_str()));
        } else if (a == "--threads") {
            n_threads = std::atoi(next(a.c_str()));
        } else if (a == "--out") {
            out_path = next(a.c_str());
        } else if (!a.empty() && a[0] != '-') {
            wav_path = a;
        } else {
            std::fprintf(stderr, "unknown arg: %s\n", a.c_str());
            return 2;
        }
    }
    if (model_path.empty() || wav_path.empty()) {
        std::fprintf(stderr,
                     "usage: %s -m model.gguf clip.wav [--backend B] "
                     "[--batch-sizes 1,2,4,8] [--iters N] [--threads N] [--out f.json]\n",
                     argv[0]);
        return 2;
    }
    if (iters < 1) {
        iters = 1;
    }

    struct transcribe_model_load_params lp;
    transcribe_model_load_params_init(&lp);
    lp.backend = backend;
    struct transcribe_session_params sp;
    transcribe_session_params_init(&sp);
    sp.n_threads                  = n_threads;
    struct transcribe_session * s = nullptr;
    if (auto st = transcribe_open(model_path.c_str(), &lp, &sp, &s); st != TRANSCRIBE_OK) {
        std::fprintf(stderr, "open failed: %s\n", transcribe_status_string(st));
        return 1;
    }
    const char * dev = transcribe_model_backend(transcribe_get_model(s));

    std::vector<float> pcm;
    std::string        err;
    if (!transcribe_cli::load_wav_mono_16k(wav_path, pcm, err)) {
        std::fprintf(stderr, "wav: %s\n", err.c_str());
        transcribe_session_free(s);
        return 1;
    }
    const double           audio_s = (double) pcm.size() / 16000.0;
    const std::vector<int> sizes   = parse_sizes(sizes_csv);

    std::string json = "[\n";
    for (size_t si = 0; si < sizes.size(); ++si) {
        const int                  N = sizes[si];
        std::vector<const float *> pcm_ptrs(N, pcm.data());
        std::vector<int>           n_samps(N, (int) pcm.size());

        // Warmup (allocates the batch graph / buffers for this shape).
        auto        wst = transcribe_run_batch(s, pcm_ptrs.data(), n_samps.data(), N, nullptr);
        std::string row_err;
        if (wst != TRANSCRIBE_OK) {
            row_err = transcribe_status_string(wst);
        }

        const double t_sweep0 = now_ms();
        double       wall_sum = 0.0;
        for (int it = 0; it < iters && row_err.empty(); ++it) {
            const double t0 = now_ms();
            auto         st = transcribe_run_batch(s, pcm_ptrs.data(), n_samps.data(), N, nullptr);
            const double t1 = now_ms();
            if (st != TRANSCRIBE_OK) {
                row_err = transcribe_status_string(st);
                break;
            }
            wall_sum += (t1 - t0);
        }
        const double elapsed_s = (now_ms() - t_sweep0) / 1000.0;
        const double wall_mean = row_err.empty() ? wall_sum / iters : 0.0;
        const double per_utt   = row_err.empty() ? wall_mean / N : 0.0;

        char buf[512];
        std::snprintf(buf, sizeof(buf),
                      "  {\"n_batch\": %d, \"wall_mean_ms\": %.3f, \"per_utt_ms\": %.4f, "
                      "\"audio_s\": %.3f, \"n_iters\": %d, \"elapsed_s\": %.4f, "
                      "\"backend\": \"%s\", \"error\": %s}%s\n",
                      N, wall_mean, per_utt, audio_s, iters, elapsed_s, dev ? dev : "",
                      row_err.empty() ? "null" : ("\"" + json_escape(row_err) + "\"").c_str(),
                      (si + 1 < sizes.size()) ? "," : "");
        json += buf;

        std::fprintf(stderr, "n_batch=%-4d  per_utt=%8.2f ms  wall=%9.2f ms  %s\n", N, per_utt, wall_mean,
                     row_err.empty() ? "" : row_err.c_str());
    }
    json += "]\n";

    if (!out_path.empty()) {
        FILE * f = std::fopen(out_path.c_str(), "w");
        if (f) {
            std::fputs(json.c_str(), f);
            std::fclose(f);
        }
        std::fprintf(stderr, "wrote %s\n", out_path.c_str());
    } else {
        std::fputs(json.c_str(), stdout);
    }

    transcribe_session_free(s);
    return 0;
}

bool parse_device_index(const char * text, int & out) {
    if (text == nullptr || text[0] == '\0') {
        return false;
    }
    const char * end    = text + std::strlen(text);
    int          parsed = 0;
    const auto   result = std::from_chars(text, end, parsed);
    if (result.ec != std::errc{} || result.ptr != end || parsed < 0) {
        return false;
    }
    out = parsed;
    return true;
}

std::string json_escape(const char * s) {
    std::string out;
    for (const char * p = s ? s : ""; *p; ++p) {
        const unsigned char c = static_cast<unsigned char>(*p);
        if (c == '"') {
            out += "\\\"";
        } else if (c == '\\') {
            out += "\\\\";
        } else if (c == '\n') {
            out += "\\n";
        } else if (c == '\r') {
            out += "\\r";
        } else if (c == '\t') {
            out += "\\t";
        } else if (c < 0x20) {
            char buf[8];
            std::snprintf(buf, sizeof(buf), "\\u%04x", c);
            out += buf;
        } else {
            out += static_cast<char>(c);
        }
    }
    return out;
}

void configure_app(CLI::App& app, GlobalOptions& options) {
    app.set_version_flag("--version,-V", std::string("rcli ") + RCLI_VERSION);
    app.require_subcommand(0, 1);
    app.fallthrough(true);

    app.add_flag("--json", options.json, "Machine-readable JSON output on stdout");
    app.add_flag("-v,--verbose", options.verbose, "Debug logging on stderr");
    app.add_flag("-q,--quiet", options.quiet, "Errors only on stderr");
    app.add_flag("--no-progress", options.no_progress, "Disable progress rendering");
    app.add_option("--home", options.home_override,
                   "RunAnywhere home directory (default: $RUNANYWHERE_HOME or "
                   "~/.local/share/runanywhere; models live under <home>/Models)");

    // Control-plane connection. validation happens in resolve_connection().
    app.add_option("--environment", options.environment,
                   "SDK environment: development (default, keyless OSS → baked staging "
                   "backend) or production (API key + https URL).")
        ->envname("RUNANYWHERE_ENVIRONMENT")
        ->check(CLI::IsMember({"dev", "development", "prod", "production"}));
    app.add_option("--base-url", options.base_url,
                   "Backend base URL. Optional in development (baked staging URL). "
                   "Required https for production.")
        ->envname("RUNANYWHERE_BASE_URL");
    app.add_option("--api-key", options.api_key,
                   "Control-plane API key (required for production; omit for "
                   "keyless development)")
        ->envname("RUNANYWHERE_API_KEY");

    // Namespaces first (the spec grammar), then the terminal aliases, then the
    // infrastructure commands — that is the order `--help` lists them in.
    commands::register_llm(app, options);
    commands::register_vlm(app, options);
    commands::register_tool(app, options);  // must follow register_llm (extends the `llm` group)
    commands::register_stt(app, options);
    commands::register_tts(app, options);
    commands::register_vad(app, options);
    commands::register_embed(app, options);
    commands::register_rerank(app, options);
    commands::register_image(app, options);
    commands::register_diarize(app, options);
    commands::register_segment(app, options);
    commands::register_voice(app, options);
    commands::register_rag(app, options);
    commands::register_models(app, options);
    commands::register_lora(app, options);

    commands::register_llm_aliases(app, options);
    commands::register_models_aliases(app, options);

    commands::register_serve(app, options);
    commands::register_bench(app, options);
    commands::register_backends(app, options);
    commands::register_info(app, options);
    commands::register_version(app, options);
    commands::register_auth(app, options);
    commands::register_account(app, options);
    commands::register_usage(app, options);
    commands::register_editors(app, options);
    commands::register_harness(app, options);
    commands::register_telemetry(app, options);
}

void seedConnectionModesFromSettings(gridex::mcp::MCPServer& server,
                                     gridex::AppConnectionRepository& repo) {
    QSettings s;
    for (const auto& c : repo.fetchAll()) {
        QString id = QString::fromStdString(c.id);
        QString raw = s.value(QStringLiteral("mcp.connectionMode.") + id).toString();
        auto m = gridex::mcpConnectionModeFromRaw(raw.toStdString());
        if (m) server.setConnectionMode(c.id, *m);
    }
}

int runMcpStdio(int argc, char* argv[]) {
    QApplication app(argc, argv);
    QApplication::setApplicationName(QStringLiteral("Gridex"));
    QApplication::setOrganizationName(QStringLiteral("Vurakit"));
    QApplication::setOrganizationDomain(QStringLiteral("vurakit.com"));

    auto db = std::make_shared<gridex::AppDatabase>();
    db->open();

    auto repo        = std::make_unique<gridex::AppConnectionRepository>(db);
    auto secretStore = std::make_unique<gridex::SecretStore>();
    auto provider    = std::make_unique<gridex::MCPConnectionProvider>(repo.get(), secretStore.get());

    std::shared_ptr<gridex::mcp::IMCPConnectionProvider> shim(provider.get(), [](auto*){});
    auto server = std::make_unique<gridex::mcp::MCPServer>(
        shim, "1.0.0", gridex::mcp::MCPTransportMode::Stdio);

    seedConnectionModesFromSettings(*server, *repo);

    QSettings s;
    gridex::mcp::RateLimits rl;
    rl.queriesPerMinute = s.value("mcp.rateLimit.queriesPerMinute", 60).toInt();
    rl.queriesPerHour   = s.value("mcp.rateLimit.queriesPerHour",   1000).toInt();
    rl.writesPerMinute  = s.value("mcp.rateLimit.writesPerMinute",  10).toInt();
    rl.ddlPerMinute     = s.value("mcp.rateLimit.ddlPerMinute",     1).toInt();
    server->rateLimiter().setLimits(rl);

    server->start();
    // Background watcher quits Qt when stdin EOF causes the transport to stop.
    QThread* watcher = QThread::create([&]() {
        while (server->isRunning()) QThread::msleep(250);
        QMetaObject::invokeMethod(qApp, "quit", Qt::QueuedConnection);
    });
    watcher->start();
    int code = QApplication::exec();
    server->stop();
    watcher->wait(1000);
    return code;
}

void before_handle(crow::request& req, crow::response& res, context& ctx) {
        ctx.username = settings::DEFAULT_USERNAME;  // Single configured username in OSS mode

        if(!settings::AUTH_ENABLED) {
            return;  // No auth required - open mode
        }

        // Auth is enabled - token is REQUIRED
        auto auth_header = req.get_header_value("Authorization");
        if(auth_header.empty()) {
            LOG_WARN(1001, ctx.username, "Rejected request without Authorization header");
            res.code = 401;
            res.write("Authorization header required");
            res.end();
            return;
        }

        if(auth_header != settings::AUTH_TOKEN) {
            LOG_WARN(1002, ctx.username, "Rejected request with invalid Authorization header");
            res.code = 401;
            res.write("Invalid token");
            res.end();
            return;
        }
    }

