static bool HasUnshownAchievements(PlayerInfo* thePlayerInfo)
{
	if (thePlayerInfo == nullptr)
	{
		return false;
	}

	for (int i = 0; i < MAX_ACHIEVEMENTS; i++)
	{
		if (thePlayerInfo->mEarnedAchievements[i] && !thePlayerInfo->mShownAchievements[i])
		{
			return true;
		}
	}

	return false;
}

